<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Bars\AcademicWatch;use StudPulse\Domain\{Input,Reminders};use StudPulse\Integrations\WebPush;use StudPulse\Integrations\{MpeiMailbox,MpeiMailCache,MpeiMailConnections};use StudPulse\Security\{Auth,Crypto,RateLimit};final class NotificationController{public function list(Auth$a):array{[$limit,$cursor]=Input::page();[$where,$params]=$this->visible($a);if($cursor){$anchor=DB::one('SELECT created_at FROM notifications WHERE recipient_user_id=? AND id=?',[$a->user['id'],$cursor]);if($anchor){$where.=' AND (n.created_at<? OR (n.created_at=? AND n.id<?))';array_push($params,$anchor['created_at'],$anchor['created_at'],$cursor);}}if(!empty($_GET['type'])){$where.=' AND n.type=?';$params[]=Input::text($_GET,'type',40);}if(($_GET['unread']??'')==='1'){$where.=' AND n.read_at IS NULL';}$rows=DB::all("SELECT n.* FROM notifications n WHERE $where ORDER BY n.created_at DESC,n.id DESC LIMIT ".($limit+1),$params);$more=count($rows)>$limit;if($more){array_pop($rows);}foreach($rows as&$row){if($row['type']==='mpei_mail'&&preg_match('/^mpei-mail:([a-f0-9]{64}):([0-9]{1,10}):([0-9]{1,10})$/D',$row['dedupe_key'],$match)){$row['mailQuery']=['mailbox'=>$match[1],'validity'=>$match[2],'uid'=>$match[3]];if(!empty($row['received_at']))$row['receivedAt']=gmdate('c',strtotime($row['received_at'].' UTC'));}}unset($row);return['items'=>$rows,'nextCursor'=>$more?end($rows)['id']:null];}public function unread(Auth$a):array{[$where,$params]=$this->visible($a);$count=(int)DB::one("SELECT COUNT(*) AS total FROM notifications n WHERE $where AND n.read_at IS NULL",$params)['total'];$mail=null;if(!$a->apiToken&&MpeiMailbox::available()){try{if($connection=MpeiMailConnections::find($a->session['id'])){[$login]=MpeiMailConnections::credentials($connection);$mail=MpeiMailCache::unread([$a->user['id'],MpeiMailConnections::mailboxKey($login),'inbox']);}}catch(\PDOException$error){if((int)($error->errorInfo[1]??0)!==1146)throw$error;}catch(\RuntimeException|\JsonException|\SodiumException){error_log('StudPulse MPEI mail: unread counter credentials unavailable.');}}return['count'=>$count,'mailCount'=>$mail];}private function visible(Auth$a):array{$mail=$a->apiToken?" AND n.type<>'mpei_mail'":'';return["n.recipient_user_id=? AND (n.expires_at IS NULL OR n.expires_at>UTC_TIMESTAMP(6))
            AND (n.type<>'journal' OR EXISTS(SELECT 1 FROM headman_class_drafts d
                WHERE d.id=n.related_id AND d.group_id=? AND d.term_id=? AND ? IN ('headman','deputy')))$mail",[$a->user['id'],$a->membership['group_id']??'',$a->membership['term_id']??'',$a->membership['role']??'']];}public function read(Auth$a,string$id):array{[$where,$params]=$this->visible($a);DB::run("UPDATE notifications n SET n.read_at=COALESCE(n.read_at,UTC_TIMESTAMP(6)) WHERE n.id=? AND $where",[$id,...$params]);return['read'=>true];}public function delete(Auth$a,string$id):array{$a->browserOnly();[$where,$params]=$this->visible($a);DB::run("UPDATE notifications n SET n.expires_at=UTC_TIMESTAMP(6),n.read_at=COALESCE(n.read_at,UTC_TIMESTAMP(6))
            WHERE n.id=? AND $where",[$id,...$params]);return['deleted'=>true];}public function refresh(Auth$a):array{$a->browserOnly();$user=$a->user['id'];RateLimit::check('notifications-refresh:'.$user,2,60);return['reminders'=>Reminders::collect($user),'bars'=>(new AcademicWatch())->check($a)];}public function pushConfig(Auth$a):array{$a->browserOnly();$active=DB::one('SELECT id FROM push_subscriptions WHERE user_id=? AND session_id=? AND enabled=1 LIMIT 1',[$a->user['id'],$a->session['id']]);return['publicKey'=>WebPush::publicKey(),'enabled'=>$active!==null];}public function push(Auth$a,Request$r):array{$a->browserOnly();WebPush::publicKey();$endpoint=WebPush::endpoint($r->body['endpoint']??null);$keys=WebPush::subscriptionKeys($r->body['keys']??null);$hash=Crypto::hash($endpoint);DB::run("INSERT INTO push_subscriptions(id,user_id,session_id,endpoint_hash,endpoint_ciphertext,keys_encrypted,subscribed_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(6)) AS incoming
            ON DUPLICATE KEY UPDATE subscribed_at=IF(push_subscriptions.user_id<>incoming.user_id OR push_subscriptions.enabled=0,incoming.subscribed_at,push_subscriptions.subscribed_at),
            last_success_at=IF(push_subscriptions.user_id<>incoming.user_id OR push_subscriptions.enabled=0,NULL,push_subscriptions.last_success_at),
            keys_encrypted=IF(? OR push_subscriptions.user_id<>incoming.user_id,incoming.keys_encrypted,push_subscriptions.keys_encrypted),
            user_id=incoming.user_id,session_id=incoming.session_id,endpoint_ciphertext=incoming.endpoint_ciphertext,enabled=1",[DB::id(),$a->user['id'],$a->session['id'],$hash,Crypto::encrypt($endpoint),Crypto::encrypt(json_encode((object)$keys,JSON_THROW_ON_ERROR)),(int)(bool)$keys]);DB::run('DELETE FROM push_subscriptions WHERE user_id=? AND session_id=? AND endpoint_hash<>?',[$a->user['id'],$a->session['id'],$hash]);return['enabled'=>true];}public function disablePush(Auth$a,Request$r):array{$a->browserOnly();$endpoint=$r->body['endpoint']??null;if($endpoint===null){DB::run('DELETE FROM push_subscriptions WHERE user_id=? AND session_id=?',[$a->user['id'],$a->session['id']]);}else{DB::run('DELETE FROM push_subscriptions WHERE user_id=? AND endpoint_hash=?',[$a->user['id'],Crypto::hash(WebPush::endpoint($endpoint))]);}return['enabled'=>false];}public function testPush(Auth$a,Request$r):array{$a->browserOnly();$endpoint=isset($r->body['endpoint'])?WebPush::endpoint($r->body['endpoint']):null;$hash=$endpoint!==null?Crypto::hash($endpoint):null;$params=[$a->user['id'],$a->session['id'],$hash,$hash];$devices=DB::all('SELECT id,endpoint_ciphertext,keys_encrypted FROM push_subscriptions
            WHERE user_id=? AND session_id=? AND (? IS NULL OR endpoint_hash=?) AND enabled=1 LIMIT 2',$params);if(count($devices)>1){throw new ApiError(409,'PUSH_SELECT_DEVICE','Откройте настройки заново, чтобы сайт выбрал подписку текущего браузера.');}$device=$devices[0]??null;if(!$device){throw new ApiError(409,'PUSH_DISABLED','Включите Web Push на этом устройстве.');}RateLimit::check('push-test:'.$a->user['id'],3,60);$keys=WebPush::subscriptionKeys($r->body['keys']??null);if($endpoint!==null&&$keys){$cipher=Crypto::encrypt(json_encode($keys,JSON_THROW_ON_ERROR));DB::run('UPDATE push_subscriptions SET keys_encrypted=? WHERE id=? AND endpoint_ciphertext=? AND session_id=? AND user_id=?',[$cipher,$device['id'],$device['endpoint_ciphertext'],$a->session['id'],$a->user['id']]);$device['keys_encrypted']=$cipher;}if(!WebPush::deliver($device)){throw new ApiError(409,'PUSH_SUBSCRIPTION_EXPIRED','Подписка истекла. Включите Web Push снова.');}$id=DB::id();$notice=WebPush::testNotice();DB::run("INSERT INTO notifications(id,recipient_user_id,type,title,body,dedupe_key,expires_at) VALUES(?,?,'push_test',?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 1 HOUR))",[$id,$a->user['id'],$notice['title'],$notice['body'],'push-test:'.$id]);return['message'=>'Сервис Web Push принял тестовое уведомление'];}}